#!/usr/bin/env python3
"""
Self-Contained Repository Bootstrapper for AegisClaw iOS (Gemma 4 E4B + xtool Edition).
Usage: python3 bootstrap_aegisclaw_repo.py [--output-dir ./AegisClaw-iOS]
"""
import argparse
import base64
import os

FILES_B64 = {
    ".bsp/xtool.json": "ewogICJuYW1lIjogInh0b29sIiwKICAidmVyc2lvbiI6ICIxLjAuMCIsCiAgImJzcFZlcnNpb24iOiAiMi4wLjAiLAogICJsYW5ndWFnZXMiOiBbCiAgICAic3dpZnQiCiAgXSwKICAiYXJndiI6IFsKICAgICIvdXNyL2Jpbi9lbnYiLAogICAgInh0b29sIiwKICAgICJkZXYiLAogICAgImJ1aWxkLXNlcnZlciIKICBdCn0K",
    ".github/workflows/ios-ci.yml": "",
    "ANTIGRAVITY_HANDOFF.md": "",
    "Config/AegisClaw.entitlements": "",
    "Config/Info.plist": "",
    "Config/XtoolInfo.plist": "",
    "Package.swift": "",
    "README.md": "",
    "Resources/JS/DOMAccessibilityDistiller.js": "",
    "Resources/Skills/calendar-triage/SKILL.md": "",
    "Resources/Skills/daily-briefing/SKILL.md": "",
    "Resources/Skills/web-research/SKILL.md": "",
    "Sources/AegisClawApp/AegisClawApp.swift": "",
    "Sources/AegisContextMemory/AegisContextMemory.swift": "",
    "Sources/AegisCore/AegisCore.swift": "",
    "Sources/AegisEdgeLLM/AegisEdgeLLM.swift": "",
    "Sources/AegisGateway/AegisGateway.swift": "",
    "Sources/AegisHarness/AegisHarness.swift": "",
    "Sources/AegisTools/AegisTools.swift": "",
    "Tests/AegisClawTests/AegisClawTests.swift": "",
    "project.yml": "",
    "xtool.yml": "",
}

def main():
    parser = argparse.ArgumentParser(description="Materialize the complete AegisClaw-iOS repository.")
    parser.add_argument("--output-dir", default="./AegisClaw-iOS", help="Target directory path")
    args = parser.parse_args()
    for rel_path, b64_data in FILES_B64.items():
        dest = os.path.join(args.output_dir, rel_path)
        os.makedirs(os.path.dirname(dest), exist_ok=True)
        with open(dest, "wb") as f:
            f.write(base64.b64decode(b64_data))
        print(f"[OK] Wrote {dest}")
    print(f"\nSuccessfully materialized {len(FILES_B64)} files into {args.output_dir}")

if __name__ == "__main__":
    main()
